const payload = $input.item.json.body || {};
const pessoaId = payload.pessoa_id ? parseInt(payload.pessoa_id, 10) : null;
const lojaId = payload.loja_id ? parseInt(payload.loja_id, 10) : null;

if (!pessoaId) {
  throw new Error('pessoa_id é obrigatório para carregar mensagens do chat.');
}

return {
  json: {
    pessoaId,
    lojaId
  }
};

const contato = $('Consultar Contato').first().json || null;
const items = $input.all();
const mensagens = items.map(item => item.json).filter(m => m.id !== undefined);

return {
  json: {
    ok: true,
    contato,
    mensagens
  }
};
